fn has_only_one_distinct_element(arr: &Vec<i32>) -> bool {
    // If the array has 0 or 1 elements, it vacuously has only one distinct value
    if arr.len() <= 1 {
        return true;
    }
    // Take the first element as the reference
    let first = arr[0];
    // Check that every element matches the first one
    arr.iter().all(|&x| x == first)
}

